const pending = $input.first().json;
const trigger = $('WF2 Input').first().json;
const chatInput = (trigger.chatInput || '').trim();
const sessionId = trigger.sessionId;
const step = pending.step;

let response = '';
let action = 'invalid';
let updatePseudo = null;
let updateEmail = null;
let updatePasswordPlain = null;
let updateInterests = null;
let updateHour = null;
let newStep = step;

const STEPS = ['ask_pseudo','ask_email','ask_password','ask_interests','ask_hour','ask_consent'];
const stepNum = STEPS.indexOf(step) + 1;

switch (step) {
  case 'ask_pseudo':
    if (/^[a-zA-Z0-9_]{3,30}$/.test(chatInput)) {
      updatePseudo = chatInput;
      newStep = 'ask_email';
      action = 'update';
      response = `Pseudo "${chatInput}" noté ! (${stepNum}/6)\n\n(Étape 2/6) Quelle est votre adresse email ?`;
    } else {
      response = 'Pseudo invalide. Utilisez 3 à 30 caractères (lettres, chiffres, underscore).\n\nQuel pseudo souhaitez-vous ?';
    }
    break;

  case 'ask_email':
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(chatInput)) {
      updateEmail = chatInput;
      newStep = 'ask_password';
      action = 'update';
      response = `Email "${chatInput}" noté. (${stepNum}/6)\n\n(Étape 3/6) Choisissez un mot de passe (8 caractères minimum) :`;
    } else {
      response = 'Adresse email invalide. Exemple : prenom@domaine.com';
    }
    break;

  case 'ask_password':
    if (chatInput.length >= 8) {
      updatePasswordPlain = chatInput;
      newStep = 'ask_interests';
      action = 'update';
      response = `Mot de passe enregistré. (${stepNum}/6)\n\n(Étape 4/6) Quels sont vos centres d\'intérêt ?\n(Ex : IA, science, crypto, finance — séparez par des virgules)`;
    } else {
      response = 'Mot de passe trop court. Minimum 8 caractères.';
    }
    break;

  case 'ask_interests':
    var interests = chatInput
      .split(',')
      .map(function(i) { return i.trim().toLowerCase(); })
      .filter(function(i) { return i.length > 0 && i.length <= 50; })
      .slice(0, 10);
    if (interests.length > 0) {
      updateInterests = JSON.stringify(interests);
      newStep = 'ask_hour';
      action = 'update';
      response = `Intérêts : ${interests.join(', ')}. (${stepNum}/6)\n\n(Étape 5/6) À quelle heure recevoir votre newsletter ?\n(Entrez un nombre entre 0 et 23, ex : 8 pour 8h00)`;
    } else {
      response = 'Veuillez entrer au moins un centre d\'intérêt.';
    }
    break;

  case 'ask_hour':
    var hour = parseInt(chatInput, 10);
    if (!isNaN(hour) && hour >= 0 && hour <= 23) {
      updateHour = hour;
      newStep = 'ask_consent';
      action = 'update';
      response = `Newsletter prévue à ${hour}h00. (${stepNum}/6)\n\n(Étape 6/6) Consentement RGPD requis :\n\nPersona stockera votre adresse email pour vous envoyer des newsletters personnalisées. Vous pouvez vous désinscrire à tout moment via le lien en bas de chaque email.\n\nTapez OUI pour accepter et créer votre compte, ou NON pour annuler.`;
    } else {
      response = 'Heure invalide. Entrez un nombre entre 0 et 23.';
    }
    break;

  case 'ask_consent':
    var answer = chatInput.toLowerCase().replace(/[^a-z]/g, '');
    if (['oui','yes','ok','jaccepte','accepte','agree'].includes(answer)) {
      action = 'complete';
      response = `Compte créé avec succès !\n\nBienvenue ${pending.pseudo} !\nVotre newsletter arrivera chaque jour à ${pending.send_hour}h00.\n\nConnectez-vous maintenant :\nlogin ${pending.pseudo} <votre_mot_de_passe>`;
    } else if (['non','no','annuler','cancel','refuse'].includes(answer)) {
      action = 'cancel';
      response = 'Inscription annulée. Vos données temporaires ont été supprimées.\n\nTapez register pour recommencer.';
    } else {
      response = 'Répondez par OUI (accepter et créer le compte) ou NON (annuler).';
    }
    break;

  default:
    response = 'Étape inconnue. Tapez register pour recommencer.';
    action = 'cancel';
}

return [{
  json: {
    sessionId,
    step,
    newStep,
    action,
    response,
    updatePseudo: updatePseudo || ' ',
    updateEmail: updateEmail || ' ',
    updatePasswordPlain: updatePasswordPlain || ' ',
    updateInterests: updateInterests || ' ',
    updateHour: updateHour !== null ? String(updateHour) : ' ',
    pendingPseudo: pending.pseudo,
    pendingEmail: pending.email,
    pendingSendHour: pending.send_hour
  }
}];

const trigger = $input.first().json;
const chatInput = (trigger.chatInput || '').trim();
const userId = trigger.user_id;
const pseudo = trigger.pseudo;

let updateType = 'unknown';
let updateValue = null;
let response = '';

if (/email/i.test(chatInput)) {
  var emailMatch = chatInput.match(/[^\s@]+@[^\s@]+\.[^\s@]+/);
  if (emailMatch) {
    updateType = 'email';
    updateValue = emailMatch[0];
  } else {
    updateType = 'unknown';
    response = 'Pour mettre à jour votre email, précisez la nouvelle adresse :\nEx : email nouveau@domaine.com';
  }
} else if (/int[eé]r[eê]t|topic|sujet|news/i.test(chatInput)) {
  var after = (chatInput.split(/[:=]/)[1] || chatInput).trim();
  var interests = after.split(',').map(function(i) { return i.trim().toLowerCase(); }).filter(function(i) { return i.length > 0 && i.length <= 50; }).slice(0, 10);
  if (interests.length > 0) {
    updateType = 'interests';
    updateValue = JSON.stringify(interests);
  } else {
    updateType = 'unknown';
    response = 'Pour mettre à jour vos intérêts, listez-les séparés par des virgules :\nEx : intérêts: IA, science, crypto';
  }
} else if (/heure|horaire|hour|schedule/i.test(chatInput)) {
  var hourMatch = chatInput.match(/\b([01]?\d|2[0-3])\b/);
  if (hourMatch) {
    var h = parseInt(hourMatch[1], 10);
    if (h >= 0 && h <= 23) {
      updateType = 'hour';
      updateValue = h;
    }
  }
  if (updateType === 'unknown') {
    response = 'Pour changer l\'heure d\'envoi, précisez l\'heure (0-23) :\nEx : horaire 9';
  }
}

return [{
  json: { userId, pseudo, updateType, updateValue, chatInput, response }
}];
